diff --git a/c:/Users/MitchellLandreth/Git-Local/AB-Logix-CI-CD/tests/ignition/start-verification.ps1 b/c:/Users/MitchellLandreth/Git-Local/AB-Logix-CI-CD/tests/ignition/start-verification.ps1
index 0000000..0000000 100644
--- a/c:/Users/MitchellLandreth/Git-Local/AB-Logix-CI-CD/tests/ignition/start-verification.ps1
+++ b/c:/Users/MitchellLandreth/Git-Local/AB-Logix-CI-CD/tests/ignition/start-verification.ps1
@@ -1,329 +1,329 @@
 #Requires -Version 5.1
 <#
 .SYNOPSIS
 Build and start the optional Ignition Perspective human-verification session.

 .DESCRIPTION
 Builds the reviewed Rockwell VCS source into an ACD, generates an ignored Perspective project
 and bearer token, starts the Windows LDSDK bridge, and starts the pinned Ignition container.
 The script never accepts the Ignition EULA or supplies a Gateway password for the user.
 #>
 [CmdletBinding()]
 param(
     [string]$Manifest = "tests\ignition\shd-lift-station.verify.yaml",
     [string]$SourceTree = "src\controllers\SHD_BOI_Line",
     [string]$AcdFile = "build\SHD_BOI_Line.ACD",
     [ValidateRange(1, 65535)]
     [int]$BridgePort = 5095,
     [ValidateRange(1, 65535)]
     [int]$GatewayPort = 9088,
     [string]$LicenseServer = $env:RA_LICENSE_SERVER
 )

 $ErrorActionPreference = "Stop"
 Set-StrictMode -Version Latest

 $repoRoot = (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
 $composeFile = Join-Path $PSScriptRoot "compose.yaml"
 $seedDataDirectory = Join-Path $PSScriptRoot ".ignition-local\data"
 $buildRoot = Join-Path $repoRoot "build\ignition"
 $projectDirectory = Join-Path $buildRoot "project"
 $tokenFile = Join-Path $buildRoot "bridge-token.txt"
 $stateFile = Join-Path $buildRoot "session.json"
 $bridgeOutput = Join-Path $buildRoot "bridge.stdout.log"
 $bridgeError = Join-Path $buildRoot "bridge.stderr.log"
 $harnessProject = Join-Path $repoRoot "tests\harness\LogixEchoHarness\LogixEchoHarness.csproj"
 $harnessDll = Join-Path $repoRoot (
     "tests\harness\LogixEchoHarness\bin\Release\net10.0-windows\win-x64\" +
     "LogixEchoHarness.dll"
 )
 $composeProject = "acs-logix-verification"
 $bridgeProcess = $null
 $composeStarted = $false
 $composeAttempted = $false

 function Invoke-CheckedCommand {
     param(
         [Parameter(Mandatory)][string]$Executable,
         [Parameter(Mandatory)][string[]]$ArgumentList,
         [Parameter(Mandatory)][string]$Operation
     )

     & $Executable @ArgumentList
     if ($LASTEXITCODE -ne 0) {
         throw "$Operation failed with exit code $LASTEXITCODE"
     }
 }

 function Get-ComposeCommand {
     $dockerCompose = Get-Command docker-compose -CommandType Application -ErrorAction SilentlyContinue
     if ($null -ne $dockerCompose) {
         return [ordered]@{
             Executable = $dockerCompose.Source
             Prefix = @()
         }
     }

     $docker = Get-Command docker -CommandType Application -ErrorAction SilentlyContinue
     if ($null -ne $docker) {
         & $docker.Source compose version | Out-Null
         if ($LASTEXITCODE -eq 0) {
             return [ordered]@{
                 Executable = $docker.Source
                 Prefix = @("compose")
             }
         }
     }

     return $null
 }

 function New-VerificationToken {
     $bytes = New-Object byte[] 48
     $generator = [Security.Cryptography.RandomNumberGenerator]::Create()
     try {
         $generator.GetBytes($bytes)
     }
     finally {
         $generator.Dispose()
     }

     return [Convert]::ToBase64String($bytes)
 }

 function Wait-ForHttpEndpoint {
     param(
         [Parameter(Mandatory)][string]$Url,
         [Parameter(Mandatory)][string]$Description,
         [Parameter(Mandatory)][int]$Attempts,
         [System.Diagnostics.Process]$Process
     )

     for ($attempt = 1; $attempt -le $Attempts; $attempt++) {
         if ($null -ne $Process) {
             $Process.Refresh()
             if ($Process.HasExited) {
                 throw "$Description process exited with code $($Process.ExitCode)"
             }
         }

         try {
             $response = Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 2
             if ($response.StatusCode -ge 200 -and $response.StatusCode -lt 300) {
                 return
             }
         }
         catch {
             if ($attempt -eq $Attempts) {
                 throw "$Description did not become ready at $Url"
             }
         }

         Start-Sleep -Seconds 1
     }
 }

 function Stop-BridgeOnFailure {
     param([string]$Token)

     if ($null -eq $bridgeProcess -or $bridgeProcess.HasExited) {
         return $true
     }

     try {
         Invoke-RestMethod `
             -Uri "http://127.0.0.1:$BridgePort/api/shutdown" `
             -Method Post `
             -Headers @{ "X-Verification-Token" = $Token } `
             -ContentType "application/json" `
             -Body "{}" `
             -TimeoutSec 5 | Out-Null
         $bridgeProcess.WaitForExit(15000) | Out-Null
         $bridgeProcess.Refresh()
         return $bridgeProcess.HasExited
     }
     catch {
         Write-Warning "The verification bridge could not be stopped cleanly: $($_.Exception.Message)"
         return $false
     }
 }

 if ($env:ACCEPT_IGNITION_EULA -cne "Y") {
     throw (
         "Set ACCEPT_IGNITION_EULA=Y in this shell only after reviewing and accepting the " +
         "Inductive Automation Ignition EULA. This script will not accept it for you."
     )
 }

 if ([string]::IsNullOrWhiteSpace($env:GATEWAY_ADMIN_PASSWORD)) {
     $env:GATEWAY_ADMIN_PASSWORD = "localdev123!"
     Write-Warning (
         "GATEWAY_ADMIN_PASSWORD was not set, using default localdev123! for local Ignition " +
         "container startup."
     )
 }

 $compose = Get-ComposeCommand
 if ($null -eq $compose) {
     throw (
         "Docker Compose is required, but neither 'docker-compose' nor 'docker compose' " +
         "is available on PATH."
     )
 }

 if (Test-Path -LiteralPath $stateFile -PathType Leaf) {
     throw (
         "A verification session state file already exists at $stateFile. " +
         "Run tests\ignition\stop-verification.ps1 before starting another session."
     )
 }

 $echoIp = $env:ACS_LOGIX_ECHO_IP
 if ([string]::IsNullOrWhiteSpace($echoIp)) {
     $echoIp = [Environment]::GetEnvironmentVariable("ACS_LOGIX_ECHO_IP", "User")
 }
 if ([string]::IsNullOrWhiteSpace($echoIp) -or $echoIp.StartsWith("127.")) {
     throw (
         "ACS_LOGIX_ECHO_IP must name a configured non-loopback Windows adapter, such as " +
         "192.168.127.5. See docs\runbooks\setup-echo-adapter.ps1."
     )
 }
 $env:ACS_LOGIX_ECHO_IP = $echoIp

 if (-not [string]::IsNullOrWhiteSpace($LicenseServer)) {
     $env:RA_LICENSE_SERVER = $LicenseServer
     $env:ROCKWELL_LICENSE_SERVER = $LicenseServer
 }

 New-Item -ItemType Directory -Force -Path $buildRoot | Out-Null
 New-Item -ItemType Directory -Force -Path $seedDataDirectory | Out-Null
 $token = New-VerificationToken
 $utf8NoBom = New-Object Text.UTF8Encoding($false)
 [IO.File]::WriteAllText($tokenFile, "$token`n", $utf8NoBom)

 Push-Location $repoRoot
 try {
     Write-Host "Building ACD from Rockwell VCS source..." -ForegroundColor Cyan
     Invoke-CheckedCommand "python" @(
         "-m", "tools.logix.compile", $SourceTree, "-o", $AcdFile
     ) "Rockwell VCS ACD build"

     Write-Host "Building and validating the verification bridge..." -ForegroundColor Cyan
     Invoke-CheckedCommand "dotnet" @(
         "build", $harnessProject, "-c", "Release", "--no-restore"
     ) "Logix Echo harness build"
     Invoke-CheckedCommand "dotnet" @(
         $harnessDll,
         "verify-plan",
         "--verification", (Join-Path $repoRoot $Manifest)
     ) "human-verification manifest validation"

     if (Test-Path -LiteralPath $projectDirectory) {
         Remove-Item -LiteralPath $projectDirectory -Recurse -Force
     }
     Write-Host "Generating the Perspective project..." -ForegroundColor Cyan
     Invoke-CheckedCommand "python" @(
         (Join-Path $PSScriptRoot "generate_project.py"),
         (Join-Path $repoRoot $Manifest),
         "--output", $projectDirectory,
         "--bridge-url", "http://host.docker.internal:$BridgePort/api/evaluate",
         "--token-file", $tokenFile
     ) "Perspective project generation"

     Remove-Item -LiteralPath $bridgeOutput, $bridgeError -Force -ErrorAction SilentlyContinue
     $runId = [DateTime]::UtcNow.ToString("yyyyMMddHHmmss")
     $bridgeArguments = @(
         "`"$harnessDll`"",
         "verify-serve",
         "--verification", "`"$(Join-Path $repoRoot $Manifest)`"",
         "--token-file", "`"$tokenFile`"",
         "--acd", "`"$(Join-Path $repoRoot $AcdFile)`"",
         "--listen", "http://0.0.0.0:$BridgePort",
         "--run-id", $runId
     )
     Write-Host "Starting the allowlisted LDSDK bridge..." -ForegroundColor Cyan
     $bridgeProcess = Start-Process `
         -FilePath "dotnet" `
         -ArgumentList $bridgeArguments `
         -WorkingDirectory $repoRoot `
         -RedirectStandardOutput $bridgeOutput `
         -RedirectStandardError $bridgeError `
         -PassThru

     $session = [ordered]@{
         process_id = $bridgeProcess.Id
         started_at_utc = [DateTime]::UtcNow.ToString("o")
         bridge_url = "http://127.0.0.1:$BridgePort"
         gateway_url = "http://localhost:$GatewayPort"
         token_file = $tokenFile
         project_directory = $projectDirectory
     }
     [IO.File]::WriteAllText(
         $stateFile,
         (($session | ConvertTo-Json -Depth 3) + "`n"),
         $utf8NoBom
     )
     Wait-ForHttpEndpoint `
         -Url "http://127.0.0.1:$BridgePort/api/health" `
         -Description "LDSDK bridge" `
         -Attempts 240 `
         -Process $bridgeProcess

     Write-Host "Starting Ignition Gateway 8.3.8..." -ForegroundColor Cyan
     $env:IGNITION_HTTP_PORT = $GatewayPort.ToString()
     $composeAttempted = $true
     $composeUpArguments = @(
         $compose.Prefix + @(
             "--project-name", $composeProject,
             "--file", $composeFile,
             "up", "--detach"
         )
     )
     & $compose.Executable @composeUpArguments
     if ($LASTEXITCODE -ne 0) {
         throw "Ignition Compose startup failed with exit code $LASTEXITCODE"
     }
     $composeStarted = $true

     Wait-ForHttpEndpoint `
         -Url "http://localhost:$GatewayPort/StatusPing" `
         -Description "Ignition Gateway" `
         -Attempts 300

     Write-Host ""
     Write-Host "Human verification is ready." -ForegroundColor Green
     Write-Host (
         "Perspective: http://localhost:$GatewayPort/data/perspective/client/" +
         "ACS_Logix_Verification/"
     ) -ForegroundColor Green
     Write-Host "Stop:        .\tests\ignition\stop-verification.ps1"
 }
 catch {
     Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red
     if ($composeAttempted) {
         $composeDownArguments = @(
             $compose.Prefix + @(
                 "--project-name", $composeProject,
                 "--file", $composeFile,
                 "down"
             )
         )
         & $compose.Executable @composeDownArguments 2>$null | Out-Null
     }
     $bridgeStopped = Stop-BridgeOnFailure -Token $token
     if ($bridgeStopped) {
         Remove-Item -LiteralPath $stateFile, $tokenFile -Force -ErrorAction SilentlyContinue
         Remove-Item -LiteralPath $projectDirectory -Recurse -Force -ErrorAction SilentlyContinue
     }
     else {
         Write-Warning (
             "Bridge recovery files were retained under $buildRoot. Run " +
             "tests\ignition\stop-verification.ps1 after the bridge becomes responsive."
         )
     }
     exit 2
 }
 finally {
     Pop-Location
 }

